// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MyContract} from "../src/MyContract.sol";

contract InvMutTest is Test {
    MyContract c;
    address owner;
    function setUp() public { c = new MyContract(); owner = address(this); }
    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(amount > 0 && amount <= address(this).balance);
        vm.deal(address(c), amount);
        uint256 before = address(c).balance;
        RevertingReceiver rcv = new RevertingReceiver();
        vm.deal(actor, 1);
        vm.prank(actor);
        bool ok;
        try c.sendTo(address(rcv), amount) { ok = true; } catch { ok = false; }
        assertTrue(ok == false && address(c).balance == before,
            "sendTo must revert when the receiver rejects Ether and must not leave funds behind");
    }
}

contract RevertingReceiver {
    receive() external payable { revert(); }
}
